import{_ as s,o as i,c as l,ak as t,bd as a,be as r}from"./chunks/framework.gO8r5hi3.js";const h=JSON.parse('{"title":"Design de niveau : Utilisation de tuiles (Tilesets et Tilemaps)","description":"","frontmatter":{},"headers":[],"relativePath":"14_DesignNiveau_Tileset.md","filePath":"14_DesignNiveau_Tileset.md","lastUpdated":1769182706000}'),n={name:"14_DesignNiveau_Tileset.md"};function o(u,e,d,p,c,m){return i(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="design-de-niveau-utilisation-de-tuiles-tilesets-et-tilemaps" tabindex="-1">Design de niveau : Utilisation de tuiles (Tilesets et Tilemaps) <a class="header-anchor" href="#design-de-niveau-utilisation-de-tuiles-tilesets-et-tilemaps" aria-label="Permalink to “Design de niveau : Utilisation de tuiles (Tilesets et Tilemaps)”">​</a></h1><p>Unity offre une fonctionnalité puissante pour créer des environnements 2D en utilisant des tuiles (tilesets) et des cartes de tuiles (tilemaps). Cette approche est particulièrement utile pour les jeux de plateforme, les RPG et autres genres nécessitant des environnements répétitifs ou modulaires. Il est possible de créer des niveaux complexes rapidement en assemblant des tuiles préconçues et même d&#39;appliquer des colliders à un ensemble de tuiles pour gérer les interactions physiques.</p><p>Pour peindre des niveaux avec des tuiles dans Unity, vous devez d&#39;abord créer un tileset à partir de vos sprites. Le tileset est une collection de sprites organisés en une grille, où chaque sprite représente une tuile individuelle. Le tileset est créé dans le dossier Assets de votre projet Unity.</p><p>Ensuite, dans la scène, vous pouvez créer une Tilemap en ajoutant un GameObject de type Tilemap à votre scène. La Tilemap est un composant qui vous permet de peindre des tuiles sur une grille dans la scène. Il optimise le rendu et la gestion des tuiles, ce qui facilite la création de niveaux complexes. Il est possible d&#39;ajouter plusieurs Tilemaps à une scène pour gérer différents calques (par exemple, un calque pour le sol, un autre pour les objets décoratifs, etc.) et d&#39;ajouter un Tilemap Collider 2D pour gérer les collisions avec les tuiles peintes de manière efficace.</p><h2 id="preparation-des-images-avant-de-les-utiliser-dans-un-ensemble-de-tuiles" tabindex="-1">Préparation des images avant de les utiliser dans un ensemble de tuiles <a class="header-anchor" href="#preparation-des-images-avant-de-les-utiliser-dans-un-ensemble-de-tuiles" aria-label="Permalink to “Préparation des images avant de les utiliser dans un ensemble de tuiles”">​</a></h2><p>Avant d&#39;utiliser des images dans un tileset, assurez-vous que chaque tuile a la même taille.</p><ol><li><p><strong>Taille uniforme</strong> : Assurez-vous que toutes les tuiles ont la même taille (par exemple, 32x32 pixels ou 64x64 pixels). Cela garantit que les tuiles s&#39;alignent correctement sur la grille de la Tilemap. Modifiez la résolution <strong>Pixels Per Unit</strong>, choisissez une taille appropriée pour vos tuiles (par exemple, 32x32 pixels) sinon vous aurez de la transparence indésirable entre les tuiles ou elle seront trop petites/grandes par rapport à la grille.</p></li><li><p>Dans l&#39;Inspector, définissez le <strong>Sprite Mode</strong> sur <strong>Multiple</strong> si les images contiennent plusieurs tuiles et utilisez le sprite editor pour découper les tuiles individuellement.</p></li></ol><h2 id="creation-d-un-ensemble-de-tuiles-tileset" tabindex="-1">Création d&#39;un ensemble de tuiles (Tileset) <a class="header-anchor" href="#creation-d-un-ensemble-de-tuiles-tileset" aria-label="Permalink to “Création d&#39;un ensemble de tuiles (Tileset)”">​</a></h2><p>Commencez par créer un ensemble de tuile (tileset) à partir de vos sprites :</p><ol><li>Ouvrez Unity et allez dans le menu <strong>Window &gt; 2D &gt; Tile Palette</strong> pour ouvrir la fenêtre de palette de tuiles.</li><li>Faites glisser les tuiles découpées depuis le dossier <code>Assets</code> vers la palette de tuiles.</li><li>Enregistrez la palette de tuiles dans un dossier approprié dans votre projet.</li></ol><p><img src="'+a+'" alt="Fenêtre de création de tuile"></p><p><img src="'+r+'" alt="Organisez les tuiles dans un dossier"></p><h2 id="peindre-des-tuiles-dans-la-tilemap" tabindex="-1">Peindre des tuiles dans la Tilemap <a class="header-anchor" href="#peindre-des-tuiles-dans-la-tilemap" aria-label="Permalink to “Peindre des tuiles dans la Tilemap”">​</a></h2><ol><li>Dans la scène, faites un clic droit dans la hiérarchie et sélectionnez <strong>2D Object &gt; Tilemap</strong> pour créer une nouvelle Tilemap.</li><li>Sélectionnez la Tilemap dans la hiérarchie et ouvrez la palette de tuiles.</li><li>Sélectionnez la tuile que vous souhaitez peindre dans la palette de tuiles.</li><li>Utilisez l&#39;outil de peinture pour peindre les tuiles sur la Tilemap dans la scène.</li></ol><h2 id="effacer-des-tuiles" tabindex="-1">Effacer des tuiles <a class="header-anchor" href="#effacer-des-tuiles" aria-label="Permalink to “Effacer des tuiles”">​</a></h2><p>Pour effacer des tuiles, sélectionnez l&#39;outil de gomme dans la palette de tuiles et cliquez sur les tuiles que vous souhaitez supprimer sur la scène.</p><h2 id="organisation-des-tuiles" tabindex="-1">Organisation des tuiles <a class="header-anchor" href="#organisation-des-tuiles" aria-label="Permalink to “Organisation des tuiles”">​</a></h2><p>Utilisez les tilemaps comme des calques séparés pour organiser les différents éléments de votre niveau (sol, décorations, objets interactifs, etc.).</p><p>Cela permet de gérer plus facilement les interactions et les collisions entre les différents éléments du jeu.</p><h2 id="ordre-d-affichage-des-tilemaps" tabindex="-1">Ordre d&#39;affichage des Tilemaps <a class="header-anchor" href="#ordre-d-affichage-des-tilemaps" aria-label="Permalink to “Ordre d&#39;affichage des Tilemaps”">​</a></h2><p>Chaque Tilemap a une propriété appelée <strong>Order in Layer</strong> dans le composant <strong>Tilemap Renderer</strong>. Cette propriété détermine l&#39;ordre d&#39;affichage des Tilemaps les unes par rapport aux autres. Les Tilemaps avec un ordre plus élevé seront rendues devant de celles avec un ordre plus bas. Utilisez cette propriété pour organiser visuellement vos calques de tuiles.</p><p>Dans un tileset, les images devraient toujours être de la même taille (par exemple, 32x32 pixels ou 64x64 pixels) pour assurer une cohérence lors de la peinture des tuiles dans la Tilemap. Assurez-vous que les tuiles s&#39;alignent correctement sur la grille.</p><h2 id="ajout-de-colliders-aux-tuiles" tabindex="-1">Ajout de colliders aux tuiles <a class="header-anchor" href="#ajout-de-colliders-aux-tuiles" aria-label="Permalink to “Ajout de colliders aux tuiles”">​</a></h2><p>Pour gérer les collisions avec les tuiles peintes, vous pouvez ajouter un composant <strong>Tilemap Collider 2D</strong> à votre Tilemap :</p><ol><li>Sélectionnez la Tilemap dans la hiérarchie.</li><li>Cliquez sur <strong>Add Component</strong> dans l&#39;Inspector.</li><li>Recherchez et ajoutez le composant <strong>Tilemap Collider 2D</strong>.</li><li>Si vous souhaitez que les tuiles aient des propriétés physiques (comme la gravité ou les rebonds), ajoutez également un composant <strong>Rigidbody 2D</strong> à la Tilemap et configurez-le selon vos besoins.</li></ol><p><a href="https://docs.unity3d.com/Manual/Tilemap.html" target="_blank" rel="noreferrer">Documentation officielle Unity sur les Tilemaps</a></p>',26)])])}const f=s(n,[["render",o]]);export{h as __pageData,f as default};
